CREATE DATABASE IF NOT EXISTS mahakaya_enterprise CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE mahakaya_enterprise;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,mobile VARCHAR(15) NOT NULL UNIQUE,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin') DEFAULT 'customer',city VARCHAR(80),state VARCHAR(80),address TEXT,pan VARCHAR(10),aadhaar VARCHAR(12),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_role(role));
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,designation VARCHAR(120) NOT NULL DEFAULT 'Administrator',permissions JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_admin_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE loans(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,loan_type VARCHAR(80) NOT NULL,amount DECIMAL(12,2) NOT NULL,interest_rate DECIMAL(5,2) DEFAULT 11.50,tenure_months INT DEFAULT 60,status ENUM('pending','under_review','approved','rejected','disbursed','closed') DEFAULT 'pending',occupation VARCHAR(120),company VARCHAR(160),monthly_income DECIMAL(12,2),dob DATE,remarks TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_loans_user(user_id),INDEX idx_loans_status(status),CONSTRAINT fk_loans_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE loan_documents(id INT AUTO_INCREMENT PRIMARY KEY,loan_id INT NOT NULL,document_type ENUM('aadhaar','pan','salary_slip') NOT NULL,file_path VARCHAR(255) NOT NULL,verified BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_docs_loan FOREIGN KEY(loan_id) REFERENCES loans(id) ON DELETE CASCADE);
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,loan_id INT NOT NULL,razorpay_order_id VARCHAR(120),razorpay_payment_id VARCHAR(120),amount DECIMAL(12,2) NOT NULL,status ENUM('created','paid','failed') DEFAULT 'created',paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_payments_status(status),CONSTRAINT fk_payments_loan FOREIGN KEY(loan_id) REFERENCES loans(id) ON DELETE CASCADE);
CREATE TABLE emi_schedule(id INT AUTO_INCREMENT PRIMARY KEY,loan_id INT NOT NULL,due_date DATE NOT NULL,emi_amount DECIMAL(12,2) NOT NULL,principal DECIMAL(12,2) NOT NULL,interest DECIMAL(12,2) NOT NULL,status ENUM('due','paid','overdue') DEFAULT 'due',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_emi_due(due_date,status),CONSTRAINT fk_emi_loan FOREIGN KEY(loan_id) REFERENCES loans(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,read_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_notifications_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE contact_messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL,mobile VARCHAR(15),message TEXT NOT NULL,status ENUM('new','contacted','closed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_contact_status(status));
